1	"use client";
2	
3	import { useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import type { ArtifactKind } from "@/lib/artifacts/spec";
6	import { DESCRIBE_KEY } from "./generate-calculator-form";
7	
8	type Proposal = {
9	  kind: ArtifactKind;
10	  name: string;
11	  rationale: string;
12	};
13	
14	const labels: Record<Proposal["kind"], string> = {
15	  spending_explorer: "Spending Explorer",
16	  trip_planner: "Trip Planner",
17	  goal_tracker: "Goal Tracker",
18	  custom_planner: "Custom Planner", custom_tracker: "Custom Tracker", custom_report: "Custom Report", custom_comparison: "Custom Comparison",
19	};
20	
21	export function GenerateForm() {
22	  const router = useRouter();
23	  const [description, setDescription] = useState("");
24	  const [proposal, setProposal] = useState<Proposal | null>(null);
25	  const [name, setName] = useState("");
26	  const [status, setStatus] = useState("");
27	  const [suggesting, setSuggesting] = useState(false);
28	  const [creating, setCreating] = useState(false);
29	  const active = useRef<{ id: string; controller: AbortController } | null>(null);
30	
31	  async function suggest() {
32	    setSuggesting(true);
33	    setStatus("");
34	    setProposal(null);
35	    const generation = { id: crypto.randomUUID(), controller: new AbortController() };
36	    active.current = generation;
37	    try {
38	      const response = await fetch("/api/artifacts/generate", {
39	        method: "POST",
40	        headers: { "content-type": "application/json" },
41	        body: JSON.stringify({ description, requestId: generation.id }),
42	        signal: generation.controller.signal,
43	      });
44	      const payload = await response.json().catch(() => null);
45	      if (!response.ok) throw new Error(payload?.error ?? "Suggestion failed");
46	      setProposal(payload as Proposal);
47	      setName((payload as Proposal).name);
48	      setStatus("Completed. Review the proposal before creating the tool.");
49	    } catch (error) {
50	      setStatus(generation.controller.signal.aborted ? "Canceled" : error instanceof Error ? error.message : "Suggestion failed");
51	    } finally {
52	      setSuggesting(false);
53	      if (active.current?.id === generation.id) active.current = null;
54	    }
55	  }
56	
57	  async function stop() {
58	    const generation = active.current;
59	    if (!generation) return;
60	    try {
61	      const response = await fetch(`/api/artifacts/generation/${generation.id}`, { method: "DELETE" });
62	      const payload = await response.json();
63	      if (!response.ok) throw new Error(payload.error ?? "Could not stop generation");
64	      if (payload.status === "canceled") { generation.controller.abort(); setProposal(null); setStatus("Canceled"); }
65	      else setStatus(`Request is ${payload.status}`);
66	    } catch (error) { setStatus(error instanceof Error ? error.message : "Could not stop generation"); }
67	  }
68	
69	  async function continueWithProposal() {
70	    if (!proposal) return;
71	    setCreating(true);
72	    setStatus("");
73	    try {
74	      const response = await fetch("/api/artifacts/generate", {
75	        method: "POST",
76	        headers: { "content-type": "application/json" },
77	        body: JSON.stringify({ confirm: true, kind: proposal.kind, name }),
78	      });
79	      const payload = await response.json().catch(() => null);
80	      if (!response.ok) throw new Error(payload?.error ?? "Creation failed");
81	      // Hand the description to the new tool's generator so it drafts code straight away.
82	      try { sessionStorage.setItem(`${DESCRIBE_KEY}${payload.id}`, description); } catch { /* Optional convenience. */ }
83	      router.push(`/ai/library/${payload.id}`);
84	    } catch (error) {
85	      setStatus(error instanceof Error ? error.message : "Creation failed");
86	      setCreating(false);
87	    }
88	  }
89	
90	  return (
91	    <section aria-label="AI-assisted tool suggestion" className="rounded-xl border border-border bg-card p-5 shadow-sm">
92	      <h2 className="text-lg font-semibold">Describe a tool</h2>
93	      <p className="mt-1 text-sm text-muted-foreground">
94	        AI suggests a tool type and name. Nothing is created until you choose Continue; the new tool then drafts its calculator from the same description for you to preview and accept.
95	      </p>
96	      <label className="mt-3 block text-sm font-medium" htmlFor="ai-tool-description">
97	        What should the tool help with?
98	      </label>
99	      <textarea
100	        id="ai-tool-description"
101	        value={description}
102	        onChange={(event) => setDescription(event.target.value)}
103	        maxLength={500}
104	        rows={3}
105	        placeholder="e.g. compare dining spending this month"
106	        className="mt-2 w-full rounded-lg border border-border bg-card px-3 py-2 text-sm"
107	      />
108	      <button
109	        type="button"
110	        disabled={suggesting || description.trim().length === 0}
111	        onClick={suggest}
112	        className="mt-3 rounded-lg bg-brand px-3 py-2 font-medium text-white hover:opacity-90 text-sm disabled:opacity-50"
113	      >
114	        {suggesting ? "Suggesting…" : "Suggest a tool"}
115	      </button>
116	      {suggesting && <button type="button" onClick={stop} className="ml-3 rounded border px-3 py-2 text-sm">Stop generation</button>}
117	
118	      {proposal && (
119	        <div className="mt-4 rounded-xl border border-border bg-card p-4 shadow-sm text-sm">
120	          <p>
121	            <span className="font-medium">Suggested type:</span> {labels[proposal.kind]}
122	          </p>
123	          <label className="mt-2 block font-medium" htmlFor="ai-tool-name">
124	            Suggested name
125	          </label>
126	          <input
127	            id="ai-tool-name"
128	            value={name}
129	            onChange={(event) => setName(event.target.value)}
130	            maxLength={120}
131	            className="mt-1 w-full rounded-lg border border-border bg-card px-3 py-2"
132	          />
133	          <p className="mt-2">
134	            <span className="font-medium">Why:</span> {proposal.rationale}
135	          </p>
136	          <p className="mt-2 text-xs text-muted-foreground">
137	            Continue creates this trusted {labels[proposal.kind]} template in your workspace. No custom code is generated.
138	          </p>
139	          <button
140	            type="button"
141	            disabled={creating || name.trim().length === 0}
142	            onClick={continueWithProposal}
143	            className="mt-3 rounded-lg bg-brand px-3 py-2 font-medium text-white hover:opacity-90 text-sm disabled:opacity-50"
144	          >
145	            {creating ? "Creating…" : "Continue – Create this tool"}
146	          </button>
147	        </div>
148	      )}
149	
150	      {status && (
151	        <p role="status" className="mt-3 text-sm text-muted-foreground">
152	          {status}
153	        </p>
154	      )}
155	    </section>
156	  );
157	}
