1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { DraftPreview } from "./draft-preview";
6	import { FALLBACK_CALCULATORS } from "@/lib/artifacts/templates";
7	import type { ArtifactKind } from "@/lib/artifacts/spec";
8	
9	type Draft = {
10	  baseVersionId: string | null;
11	  source: string;
12	  manifest: unknown;
13	  rationale?: string;
14	  validation: { ok: boolean; errors?: string[]; warnings?: string[] };
15	};
16	
17	const EMPTY_PARAMS: Record<string, number | string> = {};
18	export const DESCRIBE_KEY = "moneo:artifact-describe:";
19	
20	export function GenerateCalculatorForm({
21	  artifactId,
22	  kind,
23	  activeVersionId,
24	  snapshot = null,
25	  initialParams = EMPTY_PARAMS,
26	  currency,
27	  locale,
28	}: {
29	  artifactId: string;
30	  kind: ArtifactKind;
31	  activeVersionId: string | null;
32	  snapshot?: unknown;
33	  initialParams?: Record<string, number | string>;
34	  currency?: string;
35	  locale?: string;
36	}) {
37	  const router = useRouter();
38	  const [description, setDescription] = useState("");
39	  const [draft, setDraft] = useState<Draft | null>(null);
40	  const [status, setStatus] = useState("");
41	  const [working, setWorking] = useState(false);
42	  const [saving, setSaving] = useState(false);
43	  const [conflict, setConflict] = useState(false);
44	  const active = useRef<{ id: string; controller: AbortController } | null>(null);
45	
46	  // The Library's "Describe a tool" hands its text over once (kept out of the URL),
47	  // so the first draft starts without typing the description twice.
48	  useEffect(() => {
49	    const key = `${DESCRIBE_KEY}${artifactId}`;
50	    let handed = "";
51	    try { handed = sessionStorage.getItem(key)?.slice(0, 500) ?? ""; } catch { /* Storage unavailable: the user can describe it here. */ }
52	    if (!handed.trim()) return;
53	    // Consume only when the draft actually starts (StrictMode re-runs effects).
54	    const timer = setTimeout(() => {
55	      try { sessionStorage.removeItem(key); } catch { /* Ignore. */ }
56	      setDescription(handed); void suggest(handed);
57	    }, 0);
58	    return () => clearTimeout(timer);
59	    // eslint-disable-next-line react-hooks/exhaustive-deps -- one-shot handoff on mount
60	  }, [artifactId]);
61	
62	  async function suggest(text = description) {
63	    setWorking(true);
64	    setStatus("");
65	    setDraft(null);
66	    const generation = { id: crypto.randomUUID(), controller: new AbortController() };
67	    active.current = generation;
68	    try {
69	      const res = await fetch("/api/artifacts/calculator/generate", {
70	        method: "POST",
71	        headers: { "content-type": "application/json" },
72	        body: JSON.stringify({ artifactId, description: text, requestId: generation.id }),
73	        signal: generation.controller.signal,
74	      });
75	      const payload = await res.json().catch(() => null);
76	      if (!res.ok) throw new Error(payload?.error ?? "AI suggestion failed");
77	      // Replayed/retained results keep the server's original source revision.
78	      // Legacy drafts without one require an explicit replacement decision.
79	      setDraft({ ...payload, baseVersionId: payload.baseVersionId ?? null });
80	      setConflict(false);
81	      setStatus("Completed. Draft retained in Activity; review it before saving a version.");
82	    } catch (err) {
83	      setStatus(generation.controller.signal.aborted ? "Canceled" : err instanceof Error ? err.message : "AI suggestion failed");
84	    } finally {
85	      setWorking(false);
86	      if (active.current?.id === generation.id) active.current = null;
87	    }
88	  }
89	
90	  async function stop() {
91	    const generation = active.current;
92	    if (!generation) return;
93	    try {
94	      const response = await fetch(`/api/artifacts/generation/${generation.id}`, { method: "DELETE" });
95	      const payload = await response.json();
96	      if (!response.ok) throw new Error(payload.error ?? "Could not stop generation");
97	      if (payload.status === "canceled") { generation.controller.abort(); setDraft(null); setStatus("Canceled"); }
98	      else setStatus(`Request is ${payload.status}`);
99	    } catch (error) { setStatus(error instanceof Error ? error.message : "Could not stop generation"); }
100	  }
101	
102	  async function save(source: string, manifest: unknown, expectedActiveVersionId = draft?.baseVersionId ?? null) {
103	    setSaving(true);
104	    setStatus("");
105	    try {
106	      const res = await fetch(`/api/artifacts/${artifactId}/versions`, {
107	        method: "POST",
108	        headers: { "content-type": "application/json" },
109	        body: JSON.stringify({ source, manifest, expectedActiveVersionId }),
110	      });
111	      const payload = await res.json().catch(() => null);
112	      if (!res.ok) {
113	        if (res.status === 409) { setConflict(true); router.refresh(); }
114	        throw new Error(payload?.error ?? "Save failed");
115	      }
116	      if (payload?.status === "failed") {
117	        setStatus(
118	          `Candidate failed validation and was NOT activated: ${(payload?.validation?.errors ?? []).join("; ")}`,
119	        );
120	      } else {
121	        setStatus("Saved as new active version.");
122	        setDraft(null); setConflict(false);
123	      }
124	      router.refresh();
125	    } catch (err) {
126	      setStatus(err instanceof Error ? err.message : "Save failed");
127	    } finally {
128	      setSaving(false);
129	    }
130	  }
131	
132	  function useFallback() {
133	    const fb = FALLBACK_CALCULATORS[kind];
134	    setDraft({
135	      baseVersionId: activeVersionId,
136	      source: fb.source,
137	      manifest: fb.manifest,
138	      rationale: `${fb.label} (deterministic fallback, no AI used)`,
139	      validation: { ok: true },
140	    });
141	    setStatus("");
142	    setConflict(false);
143	  }
144	
145	  const button = "rounded-lg border border-border bg-background px-3 py-2 text-sm font-medium hover:bg-muted disabled:opacity-50";
146	  const primary = "rounded-lg bg-primary px-3 py-2 text-sm font-medium text-primary-foreground hover:opacity-90 disabled:opacity-50";
147	  return (
148	    <section aria-label="AI-generated calculator" className="rounded-xl border border-border bg-card p-5 shadow-sm">
149	      <h2 className="text-base font-semibold tracking-tight">Describe it</h2>
150	      <p className="mt-1 text-sm text-muted-foreground">
151	        AI drafts a small pure calculator and the sandbox previews it below. Nothing is saved until
152	        you accept it with Save. Failed candidates never replace the active version.
153	      </p>
154	      <label className="mt-3 block text-sm font-medium" htmlFor="calc-description">
155	        What should the calculator compute?
156	      </label>
157	      <textarea
158	        id="calc-description"
159	        value={description}
160	        onChange={(e) => setDescription(e.target.value)}
161	        onKeyDown={(e) => { if (e.key === "Enter" && (e.metaKey || e.ctrlKey) && description.trim() && !working && !saving) void suggest(); }}
162	        maxLength={500}
163	        rows={3}
164	        placeholder="e.g. average daily dining spend from the snapshot"
165	        className="mt-2 w-full rounded-lg border border-border bg-background px-3 py-2 text-sm"
166	      />
167	      <div className="mt-3 flex flex-wrap items-center gap-2">
168	        <button
169	          type="button"
170	          disabled={working || saving || description.trim().length === 0}
171	          onClick={() => suggest()}
172	          className={primary}
173	        >
174	          {working ? "Asking AI…" : "Suggest calculator"}
175	        </button>
176	        {working && <button type="button" onClick={stop} className={button}>Stop generation</button>}
177	        <button type="button" onClick={useFallback} disabled={working || saving} className={button}>
178	          Use safe fallback
179	        </button>
180	        {draft && (
181	          <button type="button" disabled={working || saving} onClick={() => suggest()} className={button}>
182	            Retry suggestion
183	          </button>
184	        )}
185	        <span className="text-xs text-muted-foreground">Ctrl/⌘ + Enter to suggest</span>
186	      </div>
187	
188	      {draft && (
189	        <div className="mt-4 space-y-3 text-sm">
190	          {(conflict || draft.baseVersionId !== activeVersionId) && <div role="alert" className="rounded-lg border border-amber-500/40 bg-amber-500/5 p-3">
191	            <p>The active version changed. Your draft is preserved. Review the current version in history before replacing it, or discard this draft.</p>
192	            <button type="button" disabled={saving || draft.validation.ok === false || (conflict && draft.baseVersionId === activeVersionId)} onClick={() => save(draft.source, draft.manifest, activeVersionId)} className={`mt-2 ${button}`}>Replace current version with this draft</button>
193	            <button type="button" disabled={saving} onClick={() => { setDraft(null); setConflict(false); setStatus(""); }} className={`ml-2 mt-2 ${button}`}>Discard draft</button>
194	          </div>}
195	          {draft.rationale && (
196	            <p>
197	              <span className="font-medium">Rationale:</span> {draft.rationale}
198	            </p>
199	          )}
200	          <div className="grid gap-4 lg:grid-cols-2">
201	            <div className="min-w-0 space-y-3">
202	              <div>
203	                <p className="font-medium">Proposed source (inspect before saving)</p>
204	                <pre className="mt-1 max-h-64 overflow-auto rounded-lg bg-muted p-3 font-mono text-xs">
205	                  {draft.source}
206	                </pre>
207	              </div>
208	              <details>
209	                <summary className="cursor-pointer font-medium">Manifest</summary>
210	                <pre className="mt-1 max-h-40 overflow-auto rounded-lg bg-muted p-3 font-mono text-xs">
211	                  {JSON.stringify(draft.manifest, null, 2)}
212	                </pre>
213	              </details>
214	            </div>
215	            <div className="min-w-0 rounded-lg border border-border p-3">
216	              <DraftPreview source={draft.source} manifestText={JSON.stringify(draft.manifest)} snapshot={snapshot} params={initialParams} currency={currency} locale={locale} />
217	            </div>
218	          </div>
219	          {draft.validation.ok === false && (
220	            <ul aria-label="Server validation errors" className="list-disc rounded-lg border border-destructive/40 bg-destructive/5 py-2 pl-8 pr-3 text-destructive">
221	              {(draft.validation.errors ?? []).map((e) => (
222	                <li key={e}>{e}</li>
223	              ))}
224	            </ul>
225	          )}
226	          {draft.validation.ok === true && draft.validation.warnings?.length ? (
227	            <ul className="list-disc rounded-lg border border-border bg-muted py-2 pl-8 pr-3 text-muted-foreground">
228	              {draft.validation.warnings.map((w) => (
229	                <li key={w}>{w}</li>
230	              ))}
231	            </ul>
232	          ) : null}
233	          <button
234	            type="button"
235	            disabled={saving || draft.validation.ok === false}
236	            onClick={() => save(draft.source, draft.manifest)}
237	            className={primary}
238	            title={
239	              draft.validation.ok === false
240	                ? "Fix validation errors before saving (or save via the editor to record a failed attempt)"
241	                : "Save as new version"
242	            }
243	          >
244	            {saving ? "Saving…" : "Save as new version"}
245	          </button>
246	          {draft.validation.ok === false && (
247	            <p className="text-xs text-muted-foreground">
248	              This draft failed pre-save validation. Use Retry or edit it below; saving a failing
249	              candidate records a failed version and preserves the active one.
250	            </p>
251	          )}
252	        </div>
253	      )}
254	
255	      {status && (
256	        <p role="status" className="mt-3 text-sm text-muted-foreground">
257	          {status}
258	        </p>
259	      )}
260	    </section>
261	  );
262	}
