1	"use server";
2	
3	import { redirect } from "next/navigation";
4	import { z } from "zod";
5	import { requireWorkspace } from "@/lib/auth";
6	import { artifactKindSchema, calculatorManifestSchema, normalizeCalculatorParams } from "@/lib/artifacts/spec";
7	import { tripHorizon, tripScenarioSchema, type TripScenario } from "@/lib/finance/trip-scenario";
8	import { calendarDate } from "@/lib/finance/calendar";
9	import { assertTripCostCurrency, tripScenarioForParams, tripStateForScenario } from "@/lib/artifacts/trip-params";
10	import { tripForArtifact } from "@/lib/artifacts/finance-sdk";
11	import { libraryTemplate } from "@/lib/artifacts/library-templates";
12	import { saveCandidateVersion } from "@/lib/artifacts/save-version";
13	
14	const kind = artifactKindSchema;
15	const stateRevision = z.string().regex(/^\d+$/).transform(Number).pipe(z.number().int().min(0).max(2147483646));
16	const unknownTripAccount = { error: "Unknown paying or receiving account" } as const;
17	
18	export async function createArtifact(form: FormData) {
19	  const { supabase } = await requireWorkspace();
20	  const artifactKind = kind.parse(form.get("kind"));
21	  const name = z.string().trim().min(1).max(120).parse(form.get("name"));
22	  const { data, error } = await supabase.rpc("create_trusted_artifact", { p_kind: artifactKind, p_name: name });
23	  if (error || !data) throw error ?? new Error("Artifact creation failed");
24	  redirect(`/ai/library/${data.id}`);
25	}
26	
27	// Templates create a trusted artifact, then save their reviewed code through the
28	// same validated CAS boundary as any edit. A failed save leaves the placeholder.
29	export async function createFromTemplate(form: FormData) {
30	  const context = await requireWorkspace();
31	  const template = libraryTemplate(z.string().max(60).parse(form.get("template")));
32	  if (!template) throw new Error("Unknown template");
33	  const name = z.string().trim().min(1).max(120).catch(template.name).parse(form.get("name") ?? template.name);
34	  const { data, error } = await context.supabase.rpc("create_trusted_artifact", { p_kind: template.kind, p_name: name });
35	  if (error || !data) throw error ?? new Error("Artifact creation failed");
36	  if (template.build) {
37	    const { source, manifest } = template.build(calendarDate(new Date(), context.workspace.timezone));
38	    await saveCandidateVersion({ supabase: context.supabase, workspaceId: context.workspace.id, actorId: context.user.id,
39	      artifact: { id: data.id, kind: template.kind, permissions: data.permissions }, source, manifest, expectedActiveVersionId: data.active_version_id });
40	  }
41	  redirect(`/ai/library/${data.id}`);
42	}
43	
44	// Pin controls exist on the gallery and the tool page; only these two destinations are allowed.
45	function pinDestination(form: FormData, artifactId: string) {
46	  return form.get("returnTo") === "/ai/library" ? "/ai/library" : `/ai/library/${artifactId}`;
47	}
48	
49	export async function renameArtifact(form: FormData) {
50	  const { supabase } = await requireWorkspace();
51	  const artifactId = z.uuid().parse(form.get("artifactId"));
