141	          <button type="button" onClick={() => { stopped.current = false; setParams({ ...params }); }} className={tool}>Re-run</button>
142	          <button type="button" disabled={!exportable} onClick={() => exportResult("print")} className={tool}>Print / PDF</button>
143	          <button type="button" disabled={!exportable} onClick={() => exportResult("png")} className={tool}>Export PNG</button>
144	        </div>
145	      </div>
146	
147	      <div className={`mt-4 grid gap-6 ${paramEntries.length ? "lg:grid-cols-[minmax(0,16rem)_minmax(0,1fr)]" : ""}`}>
148	        {paramEntries.length > 0 && (
149	          <form action={draft.action} className="space-y-3" aria-label="Calculator inputs">
150	            <input type="hidden" name="artifactId" value={artifactId} />
151	            <input type="hidden" name="params" value={JSON.stringify(params)} />
152	            <input type="hidden" name="expectedVersion" value={draft.expectedVersion} />
153	            {paramEntries.map(([name, def]) => (
154	              <label key={name} className="block text-sm font-medium">
155	                {def.label ?? name}{isMinorParam(name, def) ? ` (minor units, ${def.currency ?? currency ?? "currency unavailable"})` : def.unit ? ` (${def.unit})` : ""}
156	                <input
157	                  value={String(params[name] ?? "")}
158	                  disabled={draft.busy}
159	                  onChange={(e) => {
160	                    const raw = e.target.value;
161	                    setParams((p) => ({ ...p, [name]: def.type === "number" && raw.trim() !== "" ? Number(raw) : raw }));
162	                  }}
163	                  type={def.type === "number" ? "number" : "text"}
164	                  min={def.type === "number" ? def.min : undefined}
165	                  max={def.type === "number" ? def.max : undefined}
166	                  step={isMinorParam(name, def) ? "1" : "any"}
167	                  maxLength={def.type === "string" ? def.maxLength ?? 200 : undefined}
168	                  inputMode={isMinorParam(name, def) ? "numeric" : def.type === "number" ? "decimal" : "text"}
169	                  aria-invalid={Boolean(inputError)}
170	                  className="mt-1 block w-full rounded-lg border border-border bg-background px-3 py-2 font-normal tabular-nums"
171	                />
172	                {isMinorParam(name, def) && (def.currency ?? currency) && <span className="mt-1 block text-xs font-normal text-muted-foreground">100 minor units = {formatMoney(100n, (def.currency ?? currency)!, locale)}. Stored as exact minor units.</span>}
173	              </label>
174	            ))}
175	            <button type="submit" disabled={Boolean(inputError) || draft.busy || draft.conflict} className="w-full rounded-lg bg-primary px-3 py-2 text-sm font-medium text-primary-foreground hover:opacity-90 disabled:opacity-50">Save inputs</button>
176	          </form>
177	        )}
178	        <div className="min-w-0">
179	          <p role="status" className={`text-sm ${status === "error" ? "rounded-lg border border-destructive/40 bg-destructive/5 px-3 py-2 text-destructive" : "text-muted-foreground"}`}>
180	            {monthChanged && "Save inputs to load financial evidence for the selected month."}
181	            {status === "done" && !exportable && !monthChanged && "Inputs or evidence changed. Recalculating?"}
182	            {status === "running" && "Running in QuickJS/Web Worker…"}
183	            {status === "stopped" && "Stopped. Re-run to execute again."}
184	            {status === "error" && `Calculator failed: ${error}`}
185	          </p>
186	          {error && status !== "error" && <p role="alert" className="mt-2 text-sm text-destructive">{error}</p>}
187	          {exportable && output && (
188	            <div className="mt-2">
189	              <CalculatorOutputView output={output} locale={locale} currency={snapshot !== null && typeof snapshot === "object" && "currency" in snapshot && typeof snapshot.currency === "string" && snapshot.currency ? snapshot.currency : currency} />
190	            </div>
191	          )}
192	        </div>
193	      </div>
194	      <StateDraftRecovery {...draft} />
195	      <p className="mt-4 border-t border-border pt-3 text-xs text-muted-foreground">
196	        Illustrative results from dated financial evidence. Validation checks execution and output shape; it does not verify financial claims. Exports include inputs and evidence so unknown or partial data stays visible.
197	      </p>
198	    </section>
199	  );
200	}
